# Company marks in the "facet" app-icon style from the prototypes repo (workspace-ai-demo's app
# icons, generated by its facets/gen.py): a solid ink silhouette cut into convex planes, every
# plane inset by half of one gap width, holes knocked out in the tile colour, no strokes, drawn in
# a 100-unit box and scaled so every mark fills the same 62-unit square.
#
# Run: python3 scripts/facets/company-marks.py  → writes src/content/company-marks.ts and a preview
import json, math, os

G = 4.6
H = G / 2

def area(p):
    return sum(p[i][0]*p[(i+1)%len(p)][1] - p[(i+1)%len(p)][0]*p[i][1] for i in range(len(p))) / 2

def inset(poly, d=H):
    if area(poly) < 0: poly = poly[::-1]
    n = len(poly); lines = []
    for i in range(n):
        (x1,y1),(x2,y2) = poly[i], poly[(i+1)%n]
        dx,dy = x2-x1, y2-y1; L = math.hypot(dx,dy)
        if L < 1e-9: continue
        nx,ny = -dy/L, dx/L
        lines.append(((x1+nx*d, y1+ny*d), (dx,dy)))
    out = []
    for i in range(len(lines)):
        (p,r),(q,s) = lines[i-1], lines[i]
        den = r[0]*s[1]-r[1]*s[0]
        if abs(den) < 1e-9: out.append(q); continue
        t = ((q[0]-p[0])*s[1]-(q[1]-p[1])*s[0]) / den
        out.append((p[0]+t*r[0], p[1]+t*r[1]))
    return out

def path(poly): return 'M' + ' L'.join(f'{x:.2f} {y:.2f}' for x,y in poly) + 'Z'
def arc(cx, cy, r, a0, a1, n=24): return [(cx + r*math.cos(math.radians(a0+(a1-a0)*i/n)), cy + r*math.sin(math.radians(a0+(a1-a0)*i/n))) for i in range(n+1)]
def circle(cx, cy, r, n=64): return arc(cx, cy, r, 0, 360, n)[:-1]
def capsule(x, y, w, h):  # a bar with round ends
    r = h/2
    return arc(x+w-r, y+r, r, -90, 90, 12) + arc(x+r, y+r, r, 90, 270, 12)

# SEEK: the disc, with its dotted arrow knocked out of it, pointing right
def m_seek():
    s = 10; r = 3.4; holes = []
    cols = {-2: (-1, 1), -1: (-1, 1), 0: (-2, 2), 1: (-1, 1), 2: (0, 0)}
    for c, (a, b) in cols.items():
        for k in range(a, b+1): holes.append(circle(48 + c*s, 50 + k*s, r, 24))
    return [circle(50, 50, 31, 96)], holes

# SEEK, dots only: the arrow in ink dots straight on the tile, no disc
def m_seek_dots():
    s = 12; r = 6; dots = []
    cols = {-2: (-1, 1), -1: (-1, 1), 0: (-2, 2), 1: (-1, 1), 2: (0, 0)}
    for c, (a, b) in cols.items():
        for k in range(a, b+1): dots.append(circle(50 + c*s, 50 + k*s, r, 24))
    return dots, []

# Best Practice: its hummingbird, in planes: wing raised, body, head, beak, tail
def m_bird():
    head = circle(66,30,12,40)
    beak = [(74,20),(96,26),(74,36)]
    body = [(28,46),(56,34),(74,44),(58,70),(32,68)]
    wing = [(30,42),(10,2),(62,32)]
    tail = [(28,64),(8,92),(50,70)]
    return [wing, body, head, beak, tail], []

# Enterprise AI: its E of three bars, the middle one short with the dot beside it
def m_eai():
    return [capsule(18,22,64,14), capsule(18,43,38,14), circle(70,50,7,40), capsule(18,64,64,14)], []

def fit(fn, box=62):
    facets, holes = fn()
    xs = [x for p in facets for x,_ in p]; ys = [y for p in facets for _,y in p]
    w, h = max(xs)-min(xs), max(ys)-min(ys); s = box/max(w,h)
    cx, cy = (max(xs)+min(xs))/2, (max(ys)+min(ys))/2
    T = lambda p: [(50+(x-cx)*s, 50+(y-cy)*s) for x,y in p]
    return [T(p) for p in facets], [T(p) for p in holes]

MARKS = [('seek', m_seek), ('seek-dots', m_seek_dots), ('best-practice', m_bird), ('eai', m_eai)]

if __name__ == '__main__':
    root = os.path.join(os.path.dirname(__file__), '..', '..')
    out = {}
    for name, fn in MARKS:
        f, h = fit(fn)
        out[name] = {'f': ' '.join(path(inset(p)) for p in f), 'h': ' '.join(path(p) for p in h)}
    ts = ('// Company marks, "facet" style. Generated by scripts/facets/company-marks.py: regenerate, don\'t hand-edit.\n'
          '// f: the mark, in ink. h: holes, cut back out in the tile colour. 100-unit box.\n'
          f'export const COMPANY_MARKS: Record<string, {{ f: string; h: string }}> = {json.dumps(out, indent=2)}\n')
    open(os.path.join(root, 'src/content/company-marks.ts'), 'w').write(ts)
    tiles = ''.join(f'<svg width="160" height="160" viewBox="0 0 100 100"><rect width="100" height="100" rx="22" fill="#F4F4F2"/><rect x=".5" y=".5" width="99" height="99" rx="21.5" fill="none" stroke="#09090B" stroke-opacity=".08"/><path d="{m["f"]}" fill="#09090B"/><path d="{m["h"]}" fill="#F4F4F2"/></svg>' for m in out.values())
    open('/tmp/company-marks.html', 'w').write(f'<body style="margin:24px;display:flex;gap:24px;background:#fff">{tiles}</body>')
